cd /workspace && docker compose exec -T backend node -e '
const get = async (url, opt) => {
  try {
    const r = await fetch(url, opt);
    const body = await r.text();
    console.log(r.status, url, "->", body.slice(0, 300).replace(/\n/g, " "));
  } catch (e) { console.log("ERR", url, e.message); }
};
(async () => {
  await get("http://backend:4000/api/v1/health");
  await get("http://backend:4000/api/v1/swagger", { method: "HEAD" });
})();
'
